using Clock=chrono::steady_clock;
static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static volatile sig_atomic_t reload_flag=0;
static void hup(int){reload_flag=1;}
static bool number(const string&s,long long&v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(LLONG_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return true;}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r"),b=s.find_last_not_of(" \t\r");return a==string::npos?"":s.substr(a,b-a+1);}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
struct Config {string listen,root,origin,trusted; int maxconn,header,htime,idle,wtime,maxreq,depth,cb,gb,refill; sockaddr_in laddr{},oaddr{}; uint32_t trust;};
static bool addr(const string&s,sockaddr_in&a){auto p=s.find(':');if(p==string::npos||s.find(':',p+1)!=string::npos)return false;long long n;if(!number(s.substr(p+1),n)||n<1||n>65535)return false;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(n);return inet_pton(AF_INET,s.substr(0,p).c_str(),&a.sin_addr)==1;}
static bool config(const string&path,Config&c){ifstream in(path);if(!in)return false;map<string,string> m;string s;while(getline(in,s)){s=trim(s);if(s.empty()||s[0]=='#')continue;auto p=s.find('=');if(p==string::npos)return false;string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(k.empty()||v.empty()||m.count(k))return false;m[k]=v;}const vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","origin_address","client_burst","global_burst","refill_ms","trusted_peer"};if(m.size()!=keys.size())return false;for(auto&k:keys)if(!m.count(k))return false;c.listen=m["listen"];c.root=m["root"];c.origin=m["origin_address"];c.trusted=m["trusted_peer"];if(c.root.empty()||c.root[0]!='/'||!addr(c.listen,c.laddr)||!addr(c.origin,c.oaddr)||inet_pton(AF_INET,c.trusted.c_str(),&c.trust)!=1)return false;struct stat st;if(stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;auto get=[&](const char*k,int&v){long long x;if(!number(m[k],x)||x<=0||x>INT_MAX)return false;v=(int)x;return true;};return get("max_connections",c.maxconn)&&get("header_bytes",c.header)&&get("header_timeout_ms",c.htime)&&get("idle_timeout_ms",c.idle)&&get("write_timeout_ms",c.wtime)&&get("max_requests",c.maxreq)&&get("pipeline_depth",c.depth)&&get("client_burst",c.cb)&&get("global_burst",c.gb)&&get("refill_ms",c.refill);}
static bool tokenchar(unsigned char c){return (c>='0'&&c<='9')||(c>='A'&&c<='Z')||(c>='a'&&c<='z')||strchr("!#$%&'*+-.^_`|~",c);}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;uint32_t v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=128;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=2048;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=65536;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if(v<min||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool pathdecode(const string&t,string&out){if(t.empty()||t[0]!='/'||t.find('#')!=string::npos)return false;auto q=t.find('?');string x=t.substr(0,q);out.clear();for(size_t i=0;i<x.size();i++){unsigned char c=x[i];if(c=='%'){if(i+2>=x.size()||hex(x[i+1])<0||hex(x[i+2])<0)return false;c=(hex(x[i+1])<<4)|hex(x[i+2]);i+=2;}if(c==0||c=='\\'||c<32||c==127)return false;out.push_back(c);}return utf8(out);}
struct Bucket{long long tokens,tick;};
struct Conn {int fd=-1,up=-1,file=-1;uint32_t peer=0;string in,out,upout,upin;size_t opos=0,upos=0;long long fileleft=0,upremain=0;off_t fileoff=0;bool closeafter=false,head=false,active=false,upheader=false,upconnect=false,updone=false,upbuffer=false,upcommitted=false;int count=0;long long idle=0,first=0,write=0,upclock=0;};
struct Server {Config cfg;string confpath;int ep=-1,listener=-1,root=-1;unordered_map<int,Conn> cs;unordered_map<int,int> owners;unordered_map<uint32_t,Bucket> clients;Bucket global{};vector<uint32_t> generation;uint32_t serial=0;
 int socklisten(const Config&c){int s=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(s<0)return -1;int one=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(s,(sockaddr*)&c.laddr,sizeof(c.laddr))||listen(s,8192)){close(s);return -1;}return s;}
 void add(int fd,uint32_t ev){if((size_t)fd>=generation.size())generation.resize((size_t)fd+1);uint32_t g=++serial;if(!g)g=++serial;generation[fd]=g;epoll_event e{};e.events=ev;e.data.u64=((uint64_t)g<<32)|(uint32_t)fd;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);}void mod(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.u64=((uint64_t)generation[fd]<<32)|(uint32_t)fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);} 
 bool start(const string&p){confpath=p;if(!config(p,cfg))return false;root=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(root<0)return false;listener=socklisten(cfg);if(listener<0)return false;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return false;add(listener,EPOLLIN);global={cfg.gb,nowms()};return true;}
 void reload(){Config n;if(!config(confpath,n))return;int r=open(n.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(r<0)return;int l=listener;if(n.listen!=cfg.listen){l=socklisten(n);if(l<0){close(r);return;}}if(l!=listener){epoll_ctl(ep,EPOLL_CTL_DEL,listener,nullptr);close(listener);listener=l;add(listener,EPOLLIN);}close(root);root=r;cfg=n;clients.clear();global={cfg.gb,nowms()};}
 void stopup(Conn&c){if(c.up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c.up,nullptr);owners.erase(c.up);close(c.up);c.up=-1;}}
 void kill(int fd){auto it=cs.find(fd);if(it==cs.end())return;Conn &c=it->second;stopup(c);if(c.file>=0)close(c.file);epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);cs.erase(it);}
 static const char* reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 429:return "Too Many Requests";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Response";}}
 void response(Conn&c,int status,long long len,const string&extra=""){c.out="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\nConnection: "+(c.closeafter?"close":"keep-alive")+"\r\n"+extra+"\r\n";c.opos=0;c.active=true;c.write=nowms();}
 void error(Conn&c,int status,bool closeit){if(closeit)c.closeafter=true;response(c,status,0);}
 void interest(Conn&c){uint32_t ev=0;if(!c.active)ev|=EPOLLIN|EPOLLRDHUP;if((!c.upbuffer||c.up<0)&&(c.opos<c.out.size()||c.fileleft>0))ev|=EPOLLOUT;mod(c.fd,ev);if(c.up>=0){uint32_t u=EPOLLRDHUP;if(c.upconnect||c.upos<c.upout.size())u|=EPOLLOUT;if(!c.upconnect&&c.upos==c.upout.size()&&(!c.upheader||c.upbuffer||c.out.size()-c.opos<262144))u|=EPOLLIN;mod(c.up,u);}}
 void refill(Bucket&b,int cap,long long t){if(b.tokens>=cap){b.tokens=cap;b.tick=t;return;}long long k=(t-b.tick)/cfg.refill;if(k>0){b.tokens=min<long long>(cap,b.tokens+k);if(b.tokens==cap)b.tick=t;else b.tick+=k*cfg.refill;}}
 bool admit(uint32_t peer,long long t){refill(global,cfg.gb,t);if(global.tokens<1)return false;auto [it,inserted]=clients.try_emplace(peer,Bucket{cfg.cb,t});refill(it->second,cfg.cb,t);if(it->second.tokens<1)return false;--it->second.tokens;--global.tokens;return true;}
 int openfile(const string&p,long long&sz){int dir=dup(root);if(dir<0)return -403;size_t i=1;bool trailing=p.size()>1&&p.back()=='/';vector<string> parts;while(i<=p.size()){size_t j=p.find('/',i);if(j==string::npos)j=p.size();string x=p.substr(i,j-i);if(x==".."){close(dir);return -403;}if(!x.empty()&&x!=".")parts.push_back(x);i=j+1;}if(parts.empty()){close(dir);return -403;}for(size_t n=0;n<parts.size();n++){bool last=n+1==parts.size();int flags=O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK;if(!last)flags|=O_DIRECTORY;int f=openat(dir,parts[n].c_str(),flags);if(f<0){int e=errno;struct stat st{};bool symlink=fstatat(dir,parts[n].c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);close(dir);return symlink?-403:(e==ENOENT||e==ENOTDIR?-404:-403);}close(dir);dir=f;}struct stat st{};if(fstat(dir,&st)||!S_ISREG(st.st_mode)||trailing){close(dir);return -403;}sz=st.st_size;return dir;}
 void beginup(Conn&c,const string&target,const string&host){int s=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(s<0){error(c,502,false);return;}int r=connect(s,(sockaddr*)&cfg.oaddr,sizeof(cfg.oaddr));if(r<0&&errno!=EINPROGRESS){close(s);error(c,502,false);return;}c.up=s;c.upconnect=r<0;c.upout=(c.head?"HEAD ":"GET ")+target+" HTTP/1.1\r\nHost: "+host+"\r\nConnection: close\r\nContent-Length: 0\r\n\r\n";c.upos=0;c.upin.clear();c.upheader=false;c.updone=false;c.upbuffer=false;c.upcommitted=false;c.upclock=nowms();c.active=true;c.write=nowms();owners[s]=c.fd;add(s,EPOLLIN|EPOLLOUT|EPOLLRDHUP);}
 void process(Conn&c){if(c.active)return;size_t end=c.in.find("\r\n\r\n");size_t check=end==string::npos?c.in.size():end+4;for(size_t i=0;i<check;i++){unsigned char ch=c.in[i];if(ch==0||(ch=='\n'&&(i==0||c.in[i-1]!='\r'))||(ch=='\r'&&i+1<check&&c.in[i+1]!='\n')){c.count++;error(c,400,true);return;}}if(end==string::npos){if(c.in.size()>(size_t)cfg.header){c.count++;c.closeafter=true;error(c,431,true);}return;}if(end+4>(size_t)cfg.header){c.count++;error(c,431,true);return;}string h=c.in.substr(0,end+2);c.in.erase(0,end+4);c.first=c.in.empty()?0:c.idle;c.count++;c.closeafter=c.count>=cfg.maxreq;c.head=false;bool bad=false;for(size_t i=0;i<h.size();i++){unsigned char x=h[i];if(!x||x=='\n'&&(i==0||h[i-1]!='\r')||x=='\r'&&(i+1>=h.size()||h[i+1]!='\n')){bad=true;break;}}size_t line=h.find("\r\n");if(line==string::npos){error(c,400,true);return;}string req=h.substr(0,line);size_t a=req.find(' '),b=a==string::npos?string::npos:req.find(' ',a+1);if(a==string::npos||b==string::npos||req.find(' ',b+1)!=string::npos||a==0||b==a+1){error(c,400,true);return;}string method=req.substr(0,a),target=req.substr(a+1,b-a-1),version=req.substr(b+1);for(unsigned char x:method)if(!tokenchar(x))bad=true;if(version!="HTTP/1.1"&&version!="HTTP/1.0")bad=true;for(unsigned char x:target)if(x<=32||x==127)bad=true;string host,real,connection;int hosts=0,reals=0,cls=0;bool te=false;long long clen=0;size_t p=line+2;while(p<h.size()){size_t e=h.find("\r\n",p);if(e==string::npos){bad=true;break;}string l=h.substr(p,e-p);p=e+2;if(l.empty())continue;size_t colon=l.find(':');if(colon==string::npos||colon==0){bad=true;break;}for(size_t i=0;i<colon;i++)if(!tokenchar((unsigned char)l[i]))bad=true;string name=lower(l.substr(0,colon)),val=trim(l.substr(colon+1));if(name=="host"){hosts++;host=val;}else if(name=="x-real-ip"){reals++;real=val;}else if(name=="connection"){connection+=","+lower(val);}else if(name=="content-length"){cls++;if(!number(val,clen))bad=true;}else if(name=="transfer-encoding")te=true;}
 if(cls>1||te||(cls&&clen!=0))bad=true;string decoded;if(!pathdecode(target,decoded))bad=true;if(version=="HTTP/1.0")c.closeafter=true;size_t x=0;while(x<connection.size()){size_t e=connection.find(',',x);if(e==string::npos)e=connection.size();if(trim(connection.substr(x,e-x))=="close")c.closeafter=true;x=e+1;}if(bad){error(c,400,true);return;}c.head=method=="HEAD";if(method!="GET"&&method!="HEAD"){error(c,405,false);return;}if(decoded=="/health"){response(c,200,3,"Content-Type: text/plain\r\n");if(!c.head)c.out+="ok\n";return;}bool gateway=target.rfind("/gateway/",0)==0;if(gateway){if(hosts!=1||host.empty()){error(c,400,true);return;}uint32_t key=c.peer;if(c.peer==cfg.trust&&reals==1){uint32_t ip;if(inet_pton(AF_INET,real.c_str(),&ip)==1)key=ip;}if(!admit(key,nowms())){error(c,429,false);return;}beginup(c,target.substr(8),host);return;}long long size=0;int f=openfile(decoded,size);if(f<0){error(c,-f,false);return;}response(c,200,size,"Content-Type: application/octet-stream\r\n");if(c.head||size==0)close(f);else{c.file=f;c.fileleft=size;c.fileoff=0;}}
 void finishresponse(Conn&c){if(c.opos<c.out.size()||c.fileleft>0||c.up>=0)return;if(c.closeafter){kill(c.fd);return;}c.active=false;c.out.clear();c.opos=0;c.idle=nowms();c.write=0;if(!c.in.empty()){if(!c.first)c.first=nowms();process(c);}interest(c);}
 void readclient(Conn&c){char buf[16384];while(!c.active){size_t limit=min<size_t>((size_t)cfg.header+16384,1048576);size_t room=limit>c.in.size()?limit-c.in.size():0;if(!room){process(c);break;}ssize_t n=recv(c.fd,buf,min(sizeof(buf),room),0);if(n>0){long long t=nowms();if(c.in.empty())c.first=t;c.idle=t;c.in.append(buf,n);process(c);if(c.active)break;}else if(n==0){kill(c.fd);return;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{kill(c.fd);return;}}if(cs.count(c.fd))interest(c);}
 void writeclient(Conn&c){while(c.opos<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.opos,c.out.size()-c.opos,MSG_NOSIGNAL);if(n>0){if(c.upheader)c.upcommitted=true;c.opos+=n;c.write=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{kill(c.fd);return;}}if(c.opos==c.out.size()){c.out.clear();c.opos=0;while(c.fileleft>0){ssize_t n=sendfile(c.fd,c.file,&c.fileoff,min<long long>(c.fileleft,1<<20));if(n>0){c.fileleft-=n;c.write=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{kill(c.fd);return;}}if(c.file>=0&&c.fileleft==0){close(c.file);c.file=-1;}}if(c.up>=0)interest(c);finishresponse(c);}
 void upstreamfail(Conn&c){stopup(c);if(!c.upcommitted){c.active=false;c.out.clear();c.opos=0;c.upbuffer=false;error(c,502,false);interest(c);}else kill(c.fd);}
 void upread(Conn&c){char buf[16384];for(;;){ssize_t n=recv(c.up,buf,sizeof(buf),0);if(n>0){c.upclock=nowms();if(!c.upheader){c.upin.append(buf,n);auto e=c.upin.find("\r\n\r\n");if(e==string::npos){if(c.upin.size()>65536){upstreamfail(c);return;}continue;}string h=c.upin.substr(0,e+2);size_t l=h.find("\r\n");if(l==string::npos||h.size()<12||h.substr(0,7)!="HTTP/1."||h[8]!=' '||!isdigit((unsigned char)h[9])||!isdigit((unsigned char)h[10])||!isdigit((unsigned char)h[11])){upstreamfail(c);return;}int status=(h[9]-'0')*100+(h[10]-'0')*10+h[11]-'0';long long len=0;int nc=0;bool bad=false;string ct;size_t pos=l+2;while(pos<h.size()){size_t z=h.find("\r\n",pos);if(z==string::npos){bad=true;break;}string ln=h.substr(pos,z-pos);pos=z+2;auto col=ln.find(':');if(col==string::npos||!col){bad=true;break;}string name=lower(ln.substr(0,col)),v=trim(ln.substr(col+1));if(name=="content-length"){nc++;if(!number(v,len))bad=true;}if(name=="transfer-encoding")bad=true;if(name=="content-type"){bool ok=true;for(unsigned char x:v)if(x<32||x==127)ok=false;if(ok)ct="Content-Type: "+v+"\r\n";}}if(bad||nc!=1||status<200||status>599){upstreamfail(c);return;}c.upheader=true;c.upremain=(c.head||status==204||status==304)?0:len;c.upbuffer=c.upremain<=32768;response(c,status,len,ct);if(c.upbuffer)c.out.reserve(c.out.size()+(size_t)c.upremain);string body=c.upin.substr(e+4);c.upin.clear();if(body.size()>(size_t)c.upremain){upstreamfail(c);return;}c.out+=body;c.upremain-=body.size();if(c.upremain==0){stopup(c);interest(c);finishresponse(c);return;}}else{if(n>c.upremain){upstreamfail(c);return;}if(c.opos){c.out.erase(0,c.opos);c.opos=0;}c.out.append(buf,n);c.upremain-=n;if(c.upremain==0){stopup(c);interest(c);finishresponse(c);return;}if(c.out.size()>262144)break;}}else if(n==0){upstreamfail(c);return;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{upstreamfail(c);return;}}interest(c);}
 void upevent(Conn&c,uint32_t ev){if(c.upconnect&&(ev&(EPOLLOUT|EPOLLERR|EPOLLHUP))){int err=0;socklen_t len=sizeof(err);if(getsockopt(c.up,SOL_SOCKET,SO_ERROR,&err,&len)||err){upstreamfail(c);return;}c.upconnect=false;}if(!c.upconnect&&c.upos<c.upout.size()&&(ev&EPOLLOUT)){while(c.upos<c.upout.size()){ssize_t n=send(c.up,c.upout.data()+c.upos,c.upout.size()-c.upos,MSG_NOSIGNAL);if(n>0){c.upos+=n;c.upclock=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{upstreamfail(c);return;}}}if(c.up>=0&&!c.upconnect&&c.upos==c.upout.size()&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR))){upread(c);return;}if(c.up>=0)interest(c);}
 void run(){epoll_event ev[512];long long scan=nowms();for(;;){if(reload_flag){reload_flag=0;reload();}int n=epoll_wait(ep,ev,512,50);long long t=nowms();for(int i=0;i<n;i++){int fd=(int)(uint32_t)ev[i].data.u64;uint32_t g=(uint32_t)(ev[i].data.u64>>32);if(fd<0||(size_t)fd>=generation.size()||generation[fd]!=g)continue;uint32_t e=ev[i].events;if(fd==listener){for(;;){sockaddr_in a{};socklen_t z=sizeof(a);int s=accept4(listener,(sockaddr*)&a,&z,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR)continue;break;}if((int)cs.size()>=cfg.maxconn){close(s);continue;}int no_delay=1;setsockopt(s,IPPROTO_TCP,TCP_NODELAY,&no_delay,sizeof(no_delay));Conn c;c.fd=s;c.peer=a.sin_addr.s_addr;c.idle=t;cs.emplace(s,move(c));add(s,EPOLLIN|EPOLLRDHUP);}continue;}auto oit=owners.find(fd);if(oit!=owners.end()){auto it=cs.find(oit->second);if(it!=cs.end())upevent(it->second,e);continue;}auto it=cs.find(fd);if(it==cs.end())continue;if(e&EPOLLIN)readclient(it->second);it=cs.find(fd);if(it==cs.end())continue;if(e&EPOLLOUT)writeclient(it->second);it=cs.find(fd);if(it==cs.end())continue;if(e&(EPOLLERR|EPOLLHUP|EPOLLRDHUP)){if(!(e&EPOLLIN))kill(fd);}}
 if(t-scan>=50){scan=t;vector<int> dead,upfail,timeout;for(auto&[fd,c]:cs){if(c.up>=0&&t-c.upclock>=cfg.wtime)upfail.push_back(fd);else if(c.active&&(c.opos<c.out.size()||c.fileleft>0)&&t-c.write>=cfg.wtime)dead.push_back(fd);else if(!c.active&&c.first&&t-c.first>=cfg.htime)timeout.push_back(fd);else if(!c.active&&!c.first&&t-c.idle>=cfg.idle)dead.push_back(fd);}for(int fd:dead)kill(fd);for(int fd:upfail){auto it=cs.find(fd);if(it!=cs.end())upstreamfail(it->second);}for(int fd:timeout){auto it=cs.find(fd);if(it!=cs.end()){error(it->second,400,true);interest(it->second);}}}}
 }
};
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;signal(SIGPIPE,SIG_IGN);struct sigaction sa{};sa.sa_handler=hup;sigemptyset(&sa.sa_mask);sigaction(SIGHUP,&sa,nullptr);Server s;if(!s.start(argv[2]))return 1;s.run();return 0;}
